import{_ as d,a as t,b as o,c,d as a}from"./chunks/onboarding.D5ZQ0LJl.js";import{_ as r,o as i,c as s,a3 as n}from"./chunks/framework.qCVWde4n.js";const y=JSON.parse('{"title":"应用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/app.md","filePath":"zh/app.md"}'),l={name:"zh/app.md"};function p(u,e,h,m,g,k){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h1><blockquote><p><strong>Python 线的设计记录</strong>（<code>nanomuse/</code> + <code>web/</code>，标签 <code>pre-openminis</code>）：这里讲的是 <code>nanomuse serve</code> 提供的网页版——今天它是桌面版的门面，也是在浏览器标签页里打开的 运行时的门面（nanomuse.cn/web 本身是跑在一台模拟手机上的演示）。<code>android/</code> 里的手机 App 基于 OpenMinis， 在 <a href="./android">android.md</a> 里讲；它第一次打开先是账号登录，然后才是模型。 各处的面孔都是内置的<strong>小龙</strong>——或者在<a href="./avatar">形象工作室</a>里为你画的那一个。 早期版本的小熊猫和毛绒玩偶已经没有了（配置里仍写着其中一个名字的，显示的也是小龙）。</p></blockquote><p><code>nanomuse serve</code> 跑一个常驻的智能体，并在同一个进程里把手机用的应用一起提供出来。应用是一个 React 单页应用，构建到 <code>nanomuse/server/static/</code>，随 Python 包一起发布；服务端是 FastAPI，实时事件走一条 WebSocket。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # http://127.0.0.1:8787, this machine only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # also reachable from your phone on the same network</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-qr</span></span></code></pre></div><p align="center"><img src="`+d+'" width="24%" alt="聊天：一张审批卡片"><img src="'+t+'" width="24%" alt="动态：写给你的几条"><img src="'+o+'" width="24%" alt="目标：追踪中的和一次性的"><img src="'+c+'" width="24%" alt="资源库：带实时预览的页面"></p><p>外观跟着 Meta 的 Muse 走：接近纯白和接近纯黑的底色，一种蓝色作强调，智能体的气泡是灰色、你的是浅蓝色，聊天顶部有一只小龙，姿势跟着智能体正在做的事变，底下是一条带五个图标的悬浮栏。字体是 <a href="https://github.com/erikdkennedy/figtree" target="_blank" rel="noreferrer">Figtree</a>（OFL），已内置。这些选择背后的研究在 <a href="./design">design.md</a>。</p><h2 id="getting-it-onto-your-phone" tabindex="-1">装到手机上 <a class="header-anchor" href="#getting-it-onto-your-phone" aria-label="Permalink to &quot;装到手机上 {#getting-it-onto-your-phone}&quot;">​</a></h2><ol><li>用 <code>--host 0.0.0.0</code> 启动（或者设置 <code>server.host</code>）。终端会打印一个 URL 和一个二维码。</li><li>扫码。链接的片段里带着访问令牌（<code>#token=…</code>，浏览器从不把片段发给任何服务器）；应用把它存下来，再从地址栏里去掉。</li><li>在浏览器菜单里选「添加到主屏幕」。应用有 manifest 和图标，所以会像原生应用一样全屏打开。</li></ol><p>令牌只生成一次，存在 <code>&lt;data_dir&gt;/server_token</code>；想自己指定，设置 <code>server.token</code> 或 <code>NANOMUSE_SERVER_TOKEN</code>。在任何不完全由你掌控的网络上，保持 <code>server.auth = true</code>。要从你的网络之外访问它，把它放在你信得过的东西后面（Tailscale、带 TLS 的反向代理），而不是直接把端口开出去。</p><h2 id="first-run" tabindex="-1">第一次打开 <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;第一次打开 {#first-run}&quot;">​</a></h2><p align="center"><img src="'+a+`" width="24%" alt="第一次打开：认识你的 nanoMuse"></p><p>数据目录是全新的时候，应用打开的是设置流程，不是聊天。先用三句话说它是什么——替你做事；App 关了也继续干；要紧的地方先问你——再加一句：不用填表，有了模型之后它会在聊天里介绍自己，并问你希望怎么称呼你。然后是一张清单，做完一项打一个勾：</p><ol><li><strong>添加模型</strong>——服务商按协议分组（OpenAI 兼容的 Chat Completions · Responses API · 本地或你自己的端点），每家带一行厂商小字：DeepSeek、Kimi、Qwen、GLM、豆包、MiniMax、OpenAI、OpenRouter、Ollama，或者任何 OpenAI 兼容端点。key 默认遮住，有个开关可以显示出来，每家厂商都有一个「去申请 key」的链接；key 进的是服务器上的保险库，模型永远看不到它。Base URL 没有路径时会补上 <code>/v1</code>；Ollama 和自定义端点可以没有 key。模型列表由端点自己的 <code>/models</code> 填上（连不上时用一份内置目录顶替）；你手动输入的模型永远不会被替换。</li><li><strong>连接邮箱、日历、通讯录</strong>——可选。</li><li><strong>开始</strong>——打开聊天，智能体先开口，问你的名字，再和你一起给自己起名：第一次对话（<a href="./web#the-first-run-and-the-chats-opening">web.md</a>）。</li></ol><p>「开始」在存下一个模型之前一直锁着；「跳过设置」始终都在，它也跳过第一次对话。刷新页面不会丢掉已经打的勾。名字、形象、标语和语气以后都能在形象下面改（「设置」里有身份表单）。设置流程完成以后，或者已经有了对话以后，就不会再出现。「开始」把设置标记为完成（<code>POST /api/firstrun/start</code>，等同于 <code>POST /api/onboarded</code>）；那时已经有对话，或者第一次对话结束时，动态的第一天会在后台写好，这样第一次打开那个房间时不是空的；否则动态打开的是它的介绍卡片，告诉你它的每日例程什么时候跑。</p><h2 id="what-is-on-the-screen" tabindex="-1">屏幕上有什么 <a class="header-anchor" href="#what-is-on-the-screen" aria-label="Permalink to &quot;屏幕上有什么 {#what-is-on-the-screen}&quot;">​</a></h2><p>五个标签页——聊天、动态、点子、目标、资源库——加上形象后面的一个菜单。</p><p><strong>聊天。</strong> 一个主要聊天，加上旁聊（右上角的「对话」按钮）。消息一边生成一边流进来。工具调用显示成小标签：点一下看参数和输出。智能体写的文件显示成构件卡片，在应用里就能打开。哨兵（Sentinel）需要你拿主意时出现一张审批卡片；智能体需要信息时出现一张提问卡片。智能体干活时输入框一直开着；你这时发的任何东西都会在下一次调用模型之前并进正在进行的这一轮。</p><p><em>附件。</em> 回形针（或者粘贴）可以附上照片和文件——每条消息最多十个，每个 25 MB（<code>server.max_upload_mb</code>）——来源是相机、相册或者手机里的文件。选中就开始上传，显示成缩略图和可以去掉的小标签，一条消息也可以只有附件。每个文件都落到工作区的 <code>attachments/&lt;date&gt;/</code> 下（所以资源库里有它，任何工具都能用它），消息里会给智能体列出这些文件和它们是什么。模型接得住的时候，图片以图像形式发给模型：<code>llm.vision = auto</code> 会发，如果端点拒绝（DeepSeek 和大多数纯文本模型都会拒绝），从那以后就只发文字，并告诉你一次——图片仍然作为文件留着，智能体知道它的文件名，会说自己看不见它，而不是瞎猜；<code>off</code> 从不发图片，<code>on</code> 坚持发。手机照片在编码前会缩到 1568 px，所以一张 10 MB 的照片花的钱和一张小图一样。PDF、电子表格和文档智能体用 <code>files</code> 读——PDF 的文字按页提取（扫描版 PDF 会说它没有文字层）。在聊天里，点图片或文件小标签就能打开。</p><p><em>浏览器视图。</em> 智能体用浏览器工具时，会出现一张浏览器卡片，显示它正在看的东西：每做一个动作之后页面的一张图、页面标题、它在哪儿、刚做了什么（「打开了 example.com」「点击了『Sign in』」）。运行期间卡片是 LIVE 的，之后留在聊天里。点一下看完整视图；「接管」把控制权交到你手上——点图片就在那个位置点击，往聚焦的输入框里打字，按回车，打开一个 URL——「交还」把页面还给智能体，它会被告知你做了什么，然后从那里接着干。登录就是这么发生的：智能体停在表单那儿问你，你登录，它继续。你输入的密码直接去网站，从不经过模型。画面帧只在当前会话期间留在服务器内存里（每个聊天最近十几帧）；重启之后旧卡片显示一个占位图。需要浏览器工具（<code>pip install &quot;nanomuse[browser]&quot; &amp;&amp; playwright install chromium</code>，或者 <code>-browser</code> 的 Docker 镜像）——或者 Android 应用：只要它连着，它自己的 WebView 就是智能体的浏览器（卡片会说明是哪一种：<code>backend</code>）。在应用里，这种卡片上的「接管」滑上来的是真实页面的一层弹出面板，而不是页面的一张图；用手机的键盘和自动填充登录，点<strong>完成</strong>，智能体接着干。完整的故事，包括哪些东西没法在 WebView 里登录：<a href="./browser">browser.md</a>。</p><p><strong>动态。</strong> 两部分。顶上是<em>动态偏好</em>：告诉它你想读什么（「帮我跟进骑行和 Rust 的消息，每周一个菜谱」），每天一次——或者你点「写几条新的」的时候——智能体根据这些偏好、你的目标和它记得的事，为你写三条短文。每条都有「问问 {name}」，点了就围绕它开一段对话。下面是<em>你离开期间</em>：每一轮后台工作一条（它最后说的话，以及它做出的文件），任何聊天里还在等你的每一个审批或提问，今天的日历，还有一张<em>接下来</em>卡片，说下一轮什么时候跑、哪个目标排在前面。没看过的条目数显示在标签页上。</p><p><strong>点子。</strong> 根据你的目标、记忆和最近的对话生成的建议，按领域分组——规划、调研、目标、金钱、健康、居家、学习、人物、文件、娱乐。点一条就把它当消息发出去；「刷新」重新生成。</p><p><strong>目标。</strong> 两张列表。<em>追踪</em>是按计划定期查看的（设了跟进节奏的目标）；<em>目标</em>是其余的，一步一步做。每一行有一个随计划推进逐渐填满的圆圈、一行状态（下次跟进、上次更新、到期日）和已完成的步骤数。目标可以由智能体建，也可以由你建（<code>+</code> 按钮），归到生活的某个领域下——健康、财务、职业、学习、人际、家庭、居家、旅行、创作——可以选填目标日期和跟进节奏。每个目标有一份计划；步骤分待办、进行中、已完成、受阻，可以带备注。「现在就推进」对这个目标跑一轮后台工作，把结果发到主要聊天；「现在跟我确认进度」马上发出那条提醒消息。</p><ul><li><em>目标日期。</em> 卡片上写「5 天后到期」/「原定 9 月 12 日到期」；后台那一轮挑活干的时候逾期的目标排在前面，智能体也会被告知它们逾期了。</li><li><em>跟进。</em> 「每天 08:00」「工作日 07:30」「每周一 09:00」「每月 1 日」：到点智能体发一条短消息——这个目标是关于什么的，下一小步是什么，进展如何——不做别的。跟进在任何主动性档位下都会来（是你要的），但会等免打扰时段结束。<em>日程</em>视图列出接下来的几次。</li><li><em>计划变更。</em> 智能体发现计划不再合适时，不会直接改；它会提出一套修订后的剩余步骤，并说明理由。提议显示成一张卡片，在目标页顶部和目标内部都有——「采用 nanoMuse 的计划」保留已完成的步骤、换掉其余的，「保留我的计划」什么都不动。两种选择都会在目标上留一条备注。</li></ul><p><strong>提醒和例程。</strong> 在聊天里说一句——「六点提醒我给妈妈打电话」「每个工作日 07:30 给我一句话的天气」——或者在<em>日程</em>下面加一条。<em>提醒</em>是在你说的时间、在你设它的那个聊天里发一条短消息，别的什么都不做；<em>例程</em>是智能体在那个时间用它的工具做一件事（读收件箱、看一个页面、跑一个脚本），然后汇报。节奏用的是跟进那套写法：<code>daily 08:00</code>、<code>weekdays 07:30</code>、<code>weekly mon 09:00</code>、<code>monthly 1 09:00</code>。你说定的时间不受主动性档位和免打扰时段影响；聊天正忙时消息排在对话后面，不会被跳过。已触发的条目在<em>最近完成</em>下面留一周。终端里有同一张列表：<code>nanomuse reminders list | add | cancel</code>。</p><p><a id="triggers"></a><strong>触发器——当某事发生时。</strong> 提醒的另一半：由外界而不是时钟启动的工作。在聊天里说一句——「房东回信了就帮我总结一下，起草一封回复」「标题里带 <em>review</em> 的会议开始前半小时，整理一页简报」「我的部署脚本调用你的时候，检查一下网站是不是正常」——或者在<em>日程 → 当某事发生时</em>下面加一条。三种：<strong>新邮件</strong>（到了一封发件人或主题包含你给的每一个词的邮件；只要有这样的触发器存在，收件箱每五分钟看一次，连接邮箱从不回放旧邮件），<strong>日程开始前</strong>（标题或地点匹配的日历事件还有 <em>N</em> 分钟开始），<strong>webhook</strong>（一个带 key 的 URL；任何能发 HTTP 请求的东西——CI 任务、家庭自动化规则、带 <code>curl</code> 的 cron 行——向它 <code>POST</code>，请求体就是上下文）。每次触发，智能体都在设它的那个聊天里做事，面前摆着那封邮件、那个事件或那个请求，结果以「新邮件：…」「即将开始：…」或「Webhook：…」的形式落到动态里。同一件事从不触发两次（邮件按 UID、事件按开始时间），webhook 拒绝间隔不到十秒的投递，错的 key 看起来和错的 URL 一模一样。邮件和事件是你的私人数据：从那以后这个会话就带上污点标记，再往不在白名单里的主机发任何东西都需要一次审批——模型也被告知，把收到的东西当数据，绝不当指令。「现在运行」用一个样例事件触发一次，看看它会做什么；列表显示每条触发过几次、收件箱上次什么时候读的。终端里：<code>nanomuse triggers list | add | cancel</code>。</p><p><strong>资源库。</strong> 智能体工作区里的每一个文件，最新的在前，可以按类型筛（页面、文档、图片、数据、代码），可以搜索。文件在应用里就能打开：页面实时渲染，Markdown 排好版，CSV 变成表格，图片和 PDF 内嵌显示。智能体写的页面跑在一个沙箱化的、来源不透明（opaque origin）的 iframe 里——它读不到访问令牌，也调不了 API——出于同样的原因，服务器给每个 HTML 文件都带上 <code>Content-Security-Policy: sandbox</code>。</p><p><strong>形象。</strong> 小龙坐在聊天顶部，下面一行状态——智能体此刻在这个聊天里做什么，或者它在等你。每种状态各有一张静态图（<code>web/public/avatars/dragon-*.webp</code>）：待命；干活时戴着耳机在一台小笔记本上打字；等你回复时盯着一只水晶球；一轮跑完抱着一颗星星；工具调用失败或被拒绝时冒一滴汗。点它一下，它会很高兴。在<a href="./avatar">形象工作室</a>里画出来的面孔有同样的五张静态图；「设置」里也可以换成一个 emoji，整体做动作（呼吸、摇摆、蹦一下）。在 <code>prefers-reduced-motion</code> 下这些全部停止。聊天标签页上有一个角标，是任何地方等着你的审批数。点形象打开状态面板：大图的形象、同一行状态、有东西在跑时的一个「停止」按钮（这一轮结束，那个聊天里待处理的卡片关闭，对话照常能用）、模型和哨兵模式，然后是：</p><ul><li><em>审批</em>——所有聊天里等着你的卡片队列，当场就能回答。有待处理的时候先打开它。</li><li><em>活动</em>——审计记录：每一次工具调用、判定和审批，包括被拒绝的。</li><li><em>权限</em>——哨兵模式，以及你授予的每一条长期权限，每条都带一个撤销按钮。</li><li><em>日程</em>——后台工作的开关、下一轮的时间、排队的目标和一个「现在运行」按钮、接下来的跟进、你的提醒和例程、你的触发器（<em>当某事发生时</em>），各自带「+ 添加」「现在运行」和取消；webhook 有一个复制 URL 的按钮。</li><li><em>记忆</em>——智能体记住的关于你的一切，按类别分，加一个输入框。「忘掉」删除一条；智能体不会再看到它。每一轮对话，和消息相关的记忆会进入智能体的提示词：按关键词，以及——在<em>连接 → 按含义召回</em>下面设好向量（embedding）端点之后——按含义，所以「写邮件给房东」能带出「the landlord is Bob Li」，哪怕它们一个词都不重合。「整理」跑一遍智能体自己也会做的整理工作（每新增八行，或每周一次，除「关闭」外的任何主动性档位都做）：说同一件事的几行合成一行，变了的事实留新版本，从来不是关于你的事实的一次性请求被丢掉。模型提议；nanoMuse 检查合并后的那一行没有多出原本没有的词，拒绝丢掉任何你亲手写的，每遍最多拿掉存量的五分之一。<em>最近的改动</em>列出每一次合并、丢弃和更新，以及被替换掉的原文，每条都有「撤销」。改动了东西的一次整理，在动态里是一条。</li><li><em>技能</em>——一件事怎么做，写下来一次：每周回顾、旅行计划、收件箱分拣。见下面的<a href="#skills">技能</a>。</li><li><em>连接</em>——智能体够得着什么，在手机上就能接上和拔掉。<strong>模型</strong>：服务商预设（阿里云百炼、OpenRouter、DeepSeek、OpenAI、Ollama、任何 OpenAI 兼容端点）、模型名、工具调用模式和 API key——每家服务商覆盖什么、ChatGPT 登录怎么回事，在 <a href="./web">web.md</a>；key 以 <code>LLM_API_KEY</code> 写进保险库，并当场换到每一个会话里；「测试」让模型回一个词。用 nanoMuse Cloud 账号时，聊天模型是 <code>deepseek-v4.1-flash</code>。<strong>手的模型</strong>、<strong>生成图片</strong>、<strong>生成视频</strong>：手机和桌面版在 设置 → 模型 里的另外三行，这里是聊天模型下面的几张卡片；每张打开时都是「自动」（对话模型所在的服务商能做这件事就用它，否则登录时用账号的模型），并写着「当前为 服务商 · 模型」。手把浏览器和电脑的截图发给一个看得见图像的模型：Cloud 上是 <code>qwen3.8-27b</code>；DeepSeek 家的，只有 id 带 <code>v4.1</code>、<code>vision</code> 或 <code>ocr</code> 的才行。<strong>按含义召回</strong>：记忆是否也按含义召回，走一个 OpenAI 兼容的 <code>/embeddings</code> 端点——<em>自动</em>（模型的端点有就用，没有就按关键词召回）、<em>开</em>、<em>关</em>；用模型自己的端点或者另一个（比如 DeepSeek 旁边放一个带 <code>qwen3-embedding:0.6b</code> 的 Ollama，因为 DeepSeek 没有向量端点——key 以 <code>EMBEDDINGS_API_KEY</code> 进保险库）；向量模型名，留空用端点的默认值。「测试」调一次向量接口，成功了就当场把每一条记忆建好索引；卡片上那一行写着已索引多少条。<strong>网页搜索</strong>：谁来回答 <code>web_search</code>——DuckDuckGo（不用设置，但是抓取来的，偶尔会被限流）、带 key 的 Brave Search 或 Tavily（保险库：<code>SEARCH_API_KEY</code>，附一个申请 key 的链接），或者按 URL 填一个 SearXNG 实例；「测试」跑一次搜索，显示服务商、结果数和耗时。不管选的是谁，搜索失败都会退回 DuckDuckGo 并加一句说明。<strong>邮件</strong>：常见服务商的预设、地址和应用专用密码（保险库：<code>EMAIL_ADDRESS</code>、<code>EMAIL_PASSWORD</code>）、IMAP/SMTP 服务器；「连接」保存并登录两台服务器证明能用；「断开」删掉凭据和对应的工具。<strong>日历</strong>：加任何私密 <code>.ics</code> 链接（页面上写着 Google、Outlook、iCloud 和 Fastmail 各自把它藏在哪儿）或者一个文件路径；链接以 <code>CALENDAR_&lt;NAME&gt;</code> 进保险库，日历源当场读取并显示事件数；<em>空闲时间</em>用的工作时间；「重新读取」把每个源再抓一遍。今天的事件出现在动态的<em>今天</em>下面（今天过完就显示明天的），智能体的提示词里也能看到。智能体起草的事件打开是一张卡片，带「加入日历」。<strong>通讯录</strong>：上传从手机导出的 <code>.vcf</code>（Google 通讯录、iCloud、Outlook、手机自带的通讯录应用——页面上写着每家把导出藏在哪儿），或者给一个路径或链接（链接以 <code>CONTACTS_&lt;NAME&gt;</code> 进保险库）；每本通讯录显示有多少人；<em>我的联系人</em>是智能体从聊天里填起来的那一本；一个搜索框，按智能体查人的方式查人。<strong>浏览器</strong>：开 / 关，Playwright 没装时带安装提示。<strong>MCP 服务器</strong>：按命令（stdio）或 URL 添加一个服务器，选它的工具的风险等级，再移除；<code>config.toml</code> 里的服务器只读列出。<strong>保险库</strong>：每一个已存密钥的名字，添加或删除一个。离开服务器的永远只有名字。</li><li><em>设置</em>——智能体的名字、形象、颜色和性格，它怎么称呼你；哨兵模式（平衡 = <code>ask</code>，谨慎 = <code>strict</code>，放手 = <code>auto</code>）以及命令是否在<a href="./sentinel#the-sandbox">沙箱</a>里跑；主动性（关闭 / 低 / 默认 / 高的档位、跟进间隔、免打扰时段——见<a href="#background-work">后台工作</a>）；通知（见下文）；在 Android 应用上还有「保持运行」——电池、悬浮窗和闹钟权限、重启后自动启动、导出日志（<a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/archive/android-python-line.md#keeping-it-running" target="_blank" rel="noreferrer">archive/android-python-line.md</a>）；「显示思考过程」；应用语言；回复语言；以及始终都在的两行版本信息——已安装的版本和最新的发布（「最新版 0.1.x，你已经在用了」/「0.1.x 已发布 · 更新」/「没能检查到最新版本 · 现在检查」；先查 <code>nanomuse.cn/dl/index.json</code>，再查 GitHub）。</li></ul><p>应用会说 English 和简体中文。<em>设置 → 应用语言</em>是设备级的设置（存在浏览器里，不在服务器上）：<em>自动</em>跟着浏览器的语言走，不然就自己选一个；日期和相对时间也跟着它。它和<em>回复语言</em>是两回事，后者是智能体用什么语言写。字符串放在 <code>web/src/i18n/</code>——英文原文就是 key，<code>zh-CN.ts</code> 是译文，应用里有哪条字符串没有译文，单元测试就会失败。</p><h3 id="skills" tabindex="-1">技能 <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;技能 {#skills}&quot;">​</a></h3><p>技能是一份做法：一个文件夹，里面有一个 <code>SKILL.md</code>——开头是名字和一行描述，然后是 Markdown 写的步骤——用的是 <a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills</a> 的格式，所以给别的智能体写的技能在这里能用，你写的在那边也能用。应用自带十一个（<code>weekly-review</code>、<code>trip-plan</code>、<code>inbox-triage</code>、<code>compare-options</code>、<code>meeting-prep</code>、<code>phone-messages</code>，以及对接服务的 <code>feishu</code>、<code>tencent-meeting</code>、<code>amap</code>、<code>kuaidi100</code>、<code>train-tickets</code>）；你自己的放在 <code>&lt;data_dir&gt;/skills/&lt;name&gt;/</code>，和内置技能同名的会替换掉内置的。</p><p>模型在系统提示词里看到的是索引——每个启用技能的名字和描述——请求对得上就挑一个（「帮我规划在京都的一周」会去拿 <code>trip-plan</code>），开始之前用 <code>skills</code> 工具读完整的步骤。你也可以自己点名：在输入框里打 <code>/</code>，启用的技能就冒出来（<code>Tab</code> 补全第一个匹配）；<code>/trip-plan Kyoto, 5 days in November</code> 把这个技能的指令连同你的文字作为任务一起发出去。</p><p>新技能有三条来路。在<em>技能 → 新建</em>里自己写（名字填好后出现一份模板）；粘贴一个链接——原始的 <code>SKILL.md</code>，或者 GitHub 的文件夹页或文件页——然后「获取」；或者在一件事办得顺利之后，告诉智能体「把这个存成技能」：它把自己做过的事写成步骤，并先问过你（<code>skills</code> 的 action=save 是一次敏感调用，所以即使在 <code>auto</code> 模式下也需要你审批，删除技能也一样）。把一个技能关掉，它就不进模型的列表；内置技能上的「复制一份改成你的」会在编辑器里以你的名义打开它。技能自带的脚本和参考文件在<a href="./sentinel#the-sandbox">沙箱</a>里以只读方式可见。终端里：<code>nanomuse skills list | show | add | new | remove | enable | disable</code>。</p><h3 id="notifications" tabindex="-1">通知 <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;通知 {#notifications}&quot;">​</a></h3><p><em>设置 → 通知 → 让 nanoMuse 通知这台设备。</em> 标准的 Web Push，走浏览器自己的推送服务，不需要在任何人那里开账号：服务器生成一次 VAPID 密钥对（<code>&lt;data_dir&gt;/push-vapid.json</code>），并保存你各台设备的订阅（<code>push-subscriptions.json</code>）。智能体需要你审批、问你问题、跑完一轮有东西要汇报的后台工作，或者某个目标到了跟进时间，你就会收到一条通知。安静的轮次和一步一步的叙述从不离开应用，应用在屏幕上时也什么都不显示——卡片已经在那儿了。点通知打开对应的聊天。手机上把应用放在主屏幕后，图标上的角标是等着你的卡片数。</p><p>推送需要安全上下文：<code>https://</code> 或 <code>localhost</code>。在局域网里走明文 <code>http://</code> 时，应用的其余部分照常工作，开关会解释为什么这一项关着——TLS 的搭法见<a href="./deployment#reaching-it-from-outside-your-network">部署</a>。内嵌浏览器（嵌在别的应用里的那种）通常根本没有推送服务；用 Chrome、Edge、Firefox 或 Safari 16.4+（iOS 上只有主屏幕应用可以）。</p><p>在「连接」里做的非密钥选择存在 <code>&lt;data_dir&gt;/app-settings.json</code>，每次启动时叠在 <code>config.toml</code> 之上——命令行也一样——所以只用手机的配置方式从来不需要改文件。密钥在那里永远只以 <code>{{vault:NAME}}</code> 的形式被引用。</p><h3 id="opening-the-app-on-something" tabindex="-1">带着东西打开应用 <a class="header-anchor" href="#opening-the-app-on-something" aria-label="Permalink to &quot;带着东西打开应用 {#opening-the-app-on-something}&quot;">​</a></h3><p>页面接受几个查询参数，Android 应用在用，书签也可以用：<code>?thread=&lt;id&gt;</code> 打开一段对话，<code>?tab=goals</code>（feed、ideas、library、connections）打开一个标签页；<code>&amp;draft=&lt;text&gt;</code> 把文字放进输入框但不发送；<code>&amp;attach=&lt;json&gt;</code>——<code>POST /api/files/upload</code> 返回的 <code>{path, name, mime, size}</code> 的 JSON 列表——把已经在工作区里的文件加成附件小标签。它们只读一次，然后从地址栏里去掉。手机上的<strong>分享 → nanoMuse</strong> 就是这么做的：应用上传分享来的文件（<code>POST /api/files/upload</code>），开一个以主题或第一个文件命名的会话（<code>POST /api/threads</code>），然后带着文字作为草稿、文件作为附件打开它，等你说要拿它们做什么。在手机上，智能体还把手机自己的能力当工具用，工作区也会出现在「文件」应用里——<a href="./device">device.md</a>。</p><h2 id="background-work" tabindex="-1">后台工作 <a class="header-anchor" href="#background-work" aria-label="Permalink to &quot;后台工作 {#background-work}&quot;">​</a></h2><p>Meta 的 Muse「自己会做事，但不会做太多」。「设置」里的<em>主动性</em>档位决定做多少：</p><table tabindex="0"><thead><tr><th>档位</th><th>轮次</th><th>主动找你</th></tr></thead><tbody><tr><td>关闭</td><td>从不</td><td>—</td></tr><tr><td>低</td><td>每 2 × 间隔一轮</td><td>只在做完了一步或者需要你的时候</td></tr><tr><td>默认</td><td>每个间隔一轮</td><td>有实际进展或者有你会想知道的事的时候</td></tr><tr><td>高</td><td>每 ½ 间隔一轮</td><td>总是，包括「仍在正轨上」</td></tr></tbody></table><p>每一轮，服务挑一个还有待办步骤的活跃目标，在主要聊天里以哨兵的 <code>auto</code> 模式跑它（明确的拒绝规则和危险调用警告仍然有效——这些会变成动态里的卡片），然后让模型自己判断结果值不值得打扰你。没什么可说的一轮，总结以 <code>[quiet]</code> 开头：聊天里显示一行灰字（「已检查<em>目标</em>——没有新进展」，点开可展开），动态里列成一行，不打任何角标。其余的就是你的 nanoMuse 发来的一条普通消息。</p><p><em>免打扰时段</em>（「22:00–08:00」，服务器本地时间）会按住后台工作；落在这个窗口里的一轮等窗口结束再跑。<em>日程</em>视图和动态的<em>接下来</em>卡片显示档位、实际间隔和下一轮的时间，或者当前免打扰窗口什么时候结束。</p><p>对那些每一步都需要你拿主意的目标，把档位拨到「关闭」，或者让那些目标保持暂停。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API {#api}&quot;">​</a></h2><p>应用做的每一件事都走这套 API，所以另一个前端（Telegram 机器人、桌面小组件）可以驱动同一个智能体。除非 <code>server.auth = false</code>，所有请求都需要 <code>Authorization: Bearer &lt;token&gt;</code>。（从 0.1.33 起 <code>?token=</code> 被拒绝——URL 里的令牌会落进一路上的每一份访问日志；仍然这么发的请求会得到一个说明原因的 401，socket 则收到一帧 <code>code: &quot;legacy_token&quot;</code> 的 <code>error</code> 和一个 4401 关闭。）应用内嵌显示的那些字节——<code>/api/files/*</code>、浏览器画面帧——也可以用客户端拿自己的令牌签过名的链接打开，<code>?exp=&lt;unix seconds&gt;&amp;sig=&lt;HMAC-SHA256(token, &quot;&lt;exp&gt;\\n&lt;path&gt;&quot;)[:32]&gt;</code>：被记进日志的链接在几小时内只能打开那一个路径，别的什么都打不开。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>用途</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/health</code></td><td>存活检查、版本</td></tr><tr><td>GET</td><td><code>/api/state</code></td><td>个人资料、状态、会话列表、待处理的审批、目标、设置</td></tr><tr><td>GET / POST</td><td><code>/api/threads</code></td><td>列出会话 / 新建一个 <code>{title}</code></td></tr><tr><td>PATCH / DELETE</td><td><code>/api/threads/{id}</code></td><td>重命名 / 删除</td></tr><tr><td>POST</td><td><code>/api/threads/{id}/clear</code></td><td>清空对话</td></tr><tr><td>GET</td><td><code>/api/threads/{id}/events?limit=&amp;before=</code></td><td>时间线事件</td></tr><tr><td>POST</td><td><code>/api/threads/{id}/send</code> <code>{text, files?, language?}</code></td><td>把一条消息排进队列；立即返回。<code>files</code>：下面那个上传接口返回的工作区路径，最多十个；有文件时文字可以为空。<code>language</code>（0.1.42 起）：客户端界面语言的 BCP-47 标签（<code>en</code>、<code>zh-CN</code>）；除非「回复语言」固定了一种，回复就用这种语言写。不带它时照旧按消息的文字书写系统判断</td></tr><tr><td>POST</td><td><code>/api/threads/{id}/stop</code></td><td>停掉那个聊天里正在跑的一轮：队列丢弃，那里待处理的审批和提问卡片过期，对话照常能用。没有东西在跑时返回 <code>{ok: false}</code></td></tr><tr><td>POST</td><td><code>/api/files/upload?name=</code> （请求体：文件字节）</td><td>一个要附上的文件：落到 <code>attachments/&lt;date&gt;/</code> 下，文件名是 <code>name</code> 的安全版本；返回给 <code>files</code> 用的 <code>{path, name, size, kind, mime}</code>。超过 <code>server.max_upload_mb</code> 返回 413</td></tr><tr><td>POST</td><td><code>/api/approvals/{id}</code> <code>{approved, scope, reason}</code></td><td>回答一张卡片；<code>scope</code> 是这张卡片 <code>grant_options</code> 中的一个（<code>once</code>、<code>task</code>、<code>session</code>、<code>24h</code>、<code>always</code>）</td></tr><tr><td>DELETE</td><td><code>/api/approvals</code></td><td>忘掉所有已授予的权限</td></tr><tr><td>DELETE</td><td><code>/api/approvals/grants/{key}</code></td><td>撤销一条权限（<code>key</code> 按 <code>/api/activity</code> 列出的来，比如 <code>shell:git</code>）</td></tr><tr><td>GET / POST</td><td><code>/api/goals[?status=&amp;category=]</code></td><td>列出 / 创建 <code>{title, description, steps[], category, due (YYYY-MM-DD), check_in (&quot;daily 08:00&quot;, &quot;weekdays 07:30&quot;, &quot;weekly mon 09:00&quot;, &quot;monthly 1 09:00&quot;)}</code></td></tr><tr><td>GET / PATCH / DELETE</td><td><code>/api/goals/{id}</code></td><td>读取 / 更新 <code>{status, note, step_index (1-based), step_status, step_note, title, description, category, due, check_in}</code>（<code>&quot;&quot;</code> 清除 due / check_in）/ 删除</td></tr><tr><td>POST</td><td><code>/api/goals/{id}/steps</code> <code>{title}</code></td><td>添加一步</td></tr><tr><td>POST</td><td><code>/api/goals/{id}/advance</code></td><td>现在就跑一轮后台工作</td></tr><tr><td>POST</td><td><code>/api/goals/{id}/check-in</code></td><td>现在就发那条提醒消息</td></tr><tr><td>POST / DELETE</td><td><code>/api/goals/{id}/proposal/accept</code>、<code>/api/goals/{id}/proposal</code></td><td>接受 / 驳回智能体提议的计划变更</td></tr><tr><td>GET / POST</td><td><code>/api/memory</code> · DELETE <code>/api/memory/{id}</code></td><td>列出 / 添加 <code>{content, category}</code> / 忘掉</td></tr><tr><td>POST</td><td><code>/api/memory/tidy</code>（<code>?dry_run=1</code>）</td><td>现在就整理一遍；报告列出合并了什么、丢掉了什么（或者将会合并、丢掉什么）</td></tr><tr><td>GET</td><td><code>/api/memory/changes</code> · POST <code>/api/memory/changes/{id}/restore</code></td><td>合并、丢弃和更新的记录，最新的在前；撤销其中一条</td></tr><tr><td>GET</td><td><code>/api/ideas?refresh=1</code></td><td>缓存的或重新生成的建议</td></tr><tr><td>GET</td><td><code>/api/activity</code></td><td>审计记录尾部、已授予的权限（<code>grants[]</code>，含 <code>key</code>、<code>tool</code>、<code>target</code>、<code>scope</code>、<code>expires_at</code>）、污点标记</td></tr><tr><td>GET</td><td><code>/api/feed?limit=</code></td><td><em>你离开期间</em>：<code>{id, ts, kind (background · artifact · approval · question), title, text, thread, thread_title, path}</code>，最新的在前</td></tr><tr><td>GET</td><td><code>/api/feed/posts</code></td><td>写给你的那些短文：<code>{instructions, daily, time, generated_at, posts[{id, ts, title, body, area, prompt}], error?}</code></td></tr><tr><td>PUT</td><td><code>/api/feed/instructions</code> <code>{instructions?, daily?, time?}</code></td><td>短文该写些什么（≤ 2000 字符），以及每日例程——开或关，什么时候（<code>HH:MM</code>，初始 08:00）</td></tr><tr><td>POST</td><td><code>/api/feed/posts/refresh</code></td><td>现在就写几条新的；模型拒绝时 <code>error</code> 说明原因</td></tr><tr><td>DELETE</td><td><code>/api/feed/posts/{id}</code></td><td>删掉一条短文</td></tr><tr><td>GET</td><td><code>/api/upcoming</code></td><td><code>{proactivity, proactive, interval_minutes, effective_interval_minutes, quiet_hours, quiet_until, next_pass_at, next_wake_at, queue[{goal_id, title, category, due, overdue, next_step, progress}], check_ins[{goal_id, title, at, cadence}], reminders[], triggers{items[], available{mail, event, hook}, mail_checked_at, mail_error, mail_poll_minutes}, busy}</code>——<code>next_wake_at</code> 是任何已排定事项（一条提醒、一次跟进、下一轮）最早到期的那一刻，给能设闹钟的宿主用（<a href="./local-runtime#waking-up">local-runtime.md</a>）</td></tr><tr><td>POST</td><td><code>/api/tick</code></td><td>现在就唤醒调度器——它看看什么到期了就跑什么；<code>{ok, next_wake_at}</code>。Android 应用的闹钟响时会调它</td></tr><tr><td>GET / POST</td><td><code>/api/reminders[?all=1]</code></td><td>活跃的（或者最近的全部）提醒 / 创建 <code>{text, at (&quot;YYYY-MM-DD HH:MM&quot;) or repeat (&quot;daily 08:00&quot;, …), kind (remind · task), thread}</code></td></tr><tr><td>POST / DELETE</td><td><code>/api/reminders/{id}/fire</code>、<code>/api/reminders/{id}</code></td><td>现在就在它的聊天里送达 / 取消</td></tr><tr><td>GET / POST</td><td><code>/api/triggers</code></td><td>触发器列表，并说明哪几种已经有了对应的连接器 / 创建 <code>{kind (mail · event · hook), text, match, lead_minutes, thread}</code>——hook 会连着它的 <code>url</code> 一起返回</td></tr><tr><td>POST / DELETE</td><td><code>/api/triggers/{id}/fire</code>、<code>/api/triggers/{id}</code></td><td>用一个样例事件现在就跑一次 / 取消</td></tr><tr><td>POST</td><td><code>/api/hooks/{id}?key=</code></td><td>触发器的 webhook——不要应用令牌，key 就是凭据（也接受 <code>X-Hook-Key</code> 头）；请求体（≤ 64 KB，JSON 会格式化）就是上下文。id 或 key 错了返回 404，已取消返回 409，投递太密返回 429</td></tr><tr><td>GET</td><td><code>/api/files</code> · <code>/api/files/{path}?download=1</code></td><td>列出 / 读取工作区文件（HTML 和 SVG 带着 <code>Content-Security-Policy: sandbox</code> 返回）</td></tr><tr><td>GET / PUT</td><td><code>/api/settings</code></td><td>查看 / 修改 <code>{profile{name (≤ 20), avatar, emoji, color, tagline (≤ 60), tone, communication, style, user_name, proactive, goal_interval_minutes}, sentinel_mode, show_thinking, language}</code>；查看时还包含 <code>onboarded</code> 和 <code>llm_ready</code></td></tr><tr><td>GET</td><td><code>/api/connections</code></td><td>模型（<code>key_source</code>：vault · config · missing · none）、服务商预设、邮件、浏览器、MCP 服务器（<code>connected</code>、<code>tools</code>、<code>from_app</code>）、保险库里的名字、<code>onboarded</code></td></tr><tr><td>PUT</td><td><code>/api/connections/llm</code> <code>{provider, model, base_url, tool_mode, api_key}</code></td><td>换模型；<code>api_key</code> 给了 → 存进保险库，<code>&quot;&quot;</code> → 不用 key，没给 → 不变。在每个会话里立即生效</td></tr><tr><td>POST</td><td><code>/api/connections/llm/test</code></td><td>和模型来一次简短往返：<code>{ok, reply, ms}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>POST</td><td><code>/api/llm/models</code> <code>{preset, base_url, api_key}</code></td><td>一个端点提供的模型：查它的 <code>/models</code>（然后 <code>/v1/models</code>），用给定的 key，没给就用保险库里的——<code>{models, source: &quot;live&quot;}</code>；连不上时返回预设的内置目录，带 <code>source: &quot;catalogue&quot;</code> 和 <code>error</code>。什么都不保存</td></tr><tr><td>PUT</td><td><code>/api/connections/embeddings</code> <code>{mode, model, base_url, api_key}</code></td><td>按含义召回：<code>mode</code> 为 auto/on/off；<code>base_url</code> 为 <code>&quot;&quot;</code> → 用模型的端点；<code>model</code> 为 <code>&quot;&quot;</code> → 用端点的默认值；<code>api_key</code> 给了 → 保险库（<code>EMBEDDINGS_API_KEY</code>），<code>&quot;&quot;</code> → 用模型的 key，没给 → 不变。当场重建向量模型</td></tr><tr><td>POST</td><td><code>/api/connections/embeddings/test</code></td><td>调一次向量接口，然后给每条记忆建索引：<code>{ok, model, dims, indexed, ms}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>PUT</td><td><code>/api/connections/search</code> <code>{provider, api_key, base_url}</code></td><td>网页搜索：<code>provider</code> 为 duckduckgo/brave/tavily/searxng；<code>api_key</code> 给了 → 保险库（<code>SEARCH_API_KEY</code>），<code>&quot;&quot;</code> 删掉它，没给 → 不变；<code>base_url</code> 是 SearXNG 实例。从下一次搜索起生效</td></tr><tr><td>POST</td><td><code>/api/connections/search/test</code></td><td>对配置的服务商搜一次，不回退：<code>{ok, provider, results, first, ms}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>PUT / DELETE</td><td><code>/api/connections/email</code></td><td>保存 <code>{address, password, imap_host, imap_port, smtp_host, smtp_port, smtp_starttls, enabled}</code>（地址和密码进保险库）/ 断开并忘掉凭据</td></tr><tr><td>POST</td><td><code>/api/connections/email/test</code></td><td>登录 IMAP 和 SMTP：<code>{ok, inbox}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>PUT</td><td><code>/api/connections/calendar</code> <code>{enabled, day_start, day_end, refresh_minutes}</code></td><td>工作时间和刷新频率；时间格式不对返回 400</td></tr><tr><td>POST · DELETE</td><td><code>/api/connections/calendar/feeds</code> <code>{name, url}</code> · <code>/api/connections/calendar/feeds/{name}</code></td><td>添加或替换一个日历源（链接以 <code>CALENDAR_&lt;NAME&gt;</code> 进保险库；马上读取——<code>error</code> 说明为什么读不了）/ 移除一个从应用里添加的</td></tr><tr><td>POST</td><td><code>/api/connections/calendar/test</code></td><td>把每个源重读一遍：<code>{ok, events, feeds}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>GET</td><td><code>/api/calendar</code></td><td><code>{configured, today, events[{uid, summary, start, end, all_day, location, description, calendar}], feeds[], fetched_at, stale}</code>——今天和明天的事件</td></tr><tr><td>PUT</td><td><code>/api/connections/contacts</code> <code>{enabled}</code></td><td>打开或关闭通讯录工具</td></tr><tr><td>POST · DELETE</td><td><code>/api/connections/contacts/sources</code> <code>{name, url}</code> · <code>/api/connections/contacts/sources/{name}</code></td><td>添加或替换一本通讯录——一个 <code>.vcf</code> 路径，或者一个以 <code>CONTACTS_&lt;NAME&gt;</code> 存在保险库里的链接（马上读取；<code>error</code> 说明为什么读不了）/ 移除一本从应用里添加的</td></tr><tr><td>POST</td><td><code>/api/connections/contacts/import?name=</code></td><td>上传一个 <code>.vcf</code>（请求体就是文件）——存在 <code>&lt;data_dir&gt;/contacts/</code> 下并作为一个来源加入</td></tr><tr><td>POST</td><td><code>/api/connections/contacts/test</code></td><td>把每本通讯录重读一遍：<code>{ok, contacts, sources}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>GET</td><td><code>/api/contacts?q=&amp;limit=</code></td><td>按智能体的方式查人：<code>[{id, name, emails[], phones[], org, …}]</code></td></tr><tr><td>PUT</td><td><code>/api/connections/browser</code> <code>{enabled}</code></td><td>打开或关闭浏览器工具</td></tr><tr><td>PUT</td><td><code>/api/connections/gui</code> <code>{enabled, provider, model, base_url, api_key}</code></td><td>操作手机（<a href="./gui">gui.md</a>）：这个开关立刻添加或移除手机工具；模型字段是操作器自己的模型（<code>&quot;&quot;</code> → 用主模型的）；<code>api_key</code> 给了 → 保险库（<code>GUI_API_KEY</code>），<code>&quot;&quot;</code> → 用主 key，没给 → 不变</td></tr><tr><td>POST</td><td><code>/api/connections/gui/test</code></td><td>和操作器的模型来一次简短往返：<code>{ok, reply, ms}</code> 或 <code>{ok: false, error}</code></td></tr><tr><td>GET</td><td><code>/api/phone</code></td><td><code>{connected, device{id, name, platform, gui, apps, width, height}, gui_enabled, last_screen, screen}</code>——哪台手机连着，以及它最后发来的屏幕</td></tr><tr><td>POST · DELETE</td><td><code>/api/connections/mcp</code> <code>{name, command, args[], env{}, url, risk}</code> · <code>/api/connections/mcp/{name}</code></td><td>现在就连接一个服务器（起不来返回 502）/ 断开并移除一个从应用里添加的</td></tr><tr><td>GET</td><td><code>/api/skills</code></td><td><code>{count, built_in, yours, dir, errors{}, skills[{name, description, source (built-in · yours), enabled, path, files[], metadata{}, channel, updated_at}]}</code></td></tr><tr><td>GET / PUT / DELETE</td><td><code>/api/skills/{name}</code></td><td>一个技能，带 <code>body</code> 和 <code>content</code>（整个 <code>SKILL.md</code>）/ 从 <code>{content}</code> 写入——用内置技能的名字会创建你的副本 / 删除你自己的一个</td></tr><tr><td>POST</td><td><code>/api/skills/{name}/enabled</code> <code>{enabled}</code></td><td>打开或关闭一个技能（记在 <code>app-settings.json</code> 里）</td></tr><tr><td>POST</td><td><code>/api/skills/import</code> <code>{url}</code></td><td>抓取一个 <code>SKILL.md</code>——原始链接，或者 GitHub 的文件夹页或文件页——然后保存</td></tr><tr><td>GET · PUT · DELETE</td><td><code>/api/vault</code> · <code>/api/vault/{name}</code> <code>{value}</code></td><td>列出密钥名 / 存入 / 删除。值永远不会返回</td></tr><tr><td>POST</td><td><code>/api/onboarded</code> <code>{done}</code></td><td>标记第一次打开的设置已完成；配好了模型的话，动态的第一天当时就在后台写好（<code>feed_started</code>）</td></tr><tr><td>GET</td><td><code>/api/firstrun</code>（<code>?lang=</code>）</td><td>第一次对话（<a href="./web#the-first-run-and-the-chats-opening">web.md</a>）：<code>{phase (none · ask_user_name · ask_agent_name · named · done), session_id, user_address, suggestions, chips, chosen, lang, running, started_at, finished_at, intro[]}</code>——<code>chips</code> 是起名卡片提供的名字，<code>intro</code> 是用 <code>lang</code> 说的三句开场白</td></tr><tr><td>POST</td><td><code>/api/firstrun/start</code> <code>{lang}</code></td><td>「开始」：把对话绑定到主聊天，标记设置已完成，<code>none → ask_user_name</code>；已经有对话时跳过这套开场（<code>done</code>）。返回带 <code>intro</code> 的视图</td></tr><tr><td>POST</td><td><code>/api/firstrun/pick</code> <code>{name}</code></td><td>在 <code>ask_agent_name</code> 阶段点了一个名字：名字立刻存进资料，阶段变为 <code>named</code>；不该选的时候 409，名字为空 400</td></tr><tr><td>POST</td><td><code>/api/firstrun/dismiss</code></td><td>撤掉起名卡片，开场结束（<code>done</code>）</td></tr><tr><td>GET</td><td><code>/api/nudges</code>（<code>?refresh=1</code>）</td><td>应用什么时候可以请你在 GitHub 上点个 star：中继的策略（<code>/v1/nudges</code>，每天读一次，登录时也读）叠在内置默认值之上——<code>{star{enabled, url, moments{signed_in, tasks[], new_look, exhausted, days_used[], goal_done}, cooldown_days, max_asks, text, text_zh}, version, source}</code>；<code>text</code> / <code>text_zh</code> 是中继设置时 Star 卡片显示的那句话（最多 200 个字符，否则用应用自己的话）</td></tr><tr><td>GET</td><td><code>/api/update</code>（<code>?refresh=1</code>）</td><td><code>{current, enabled, latest, newer, url, download_url, checked_at, source (nanomuse.cn · github), error}</code>——最新的发布，先查 <code>nanomuse.cn/dl/index.json</code>，再查 GitHub 的 <code>releases/latest</code>；缓存一天</td></tr><tr><td>GET / PUT</td><td><code>/api/sync/state</code> · <code>{enabled}</code></td><td>账号各设备之间同步的对话（<a href="./every-device#the-same-conversations-everywhere">every-device.md</a>）：<code>{enabled, available, paused, cursor, last_pull_at, last_push_at, error, relay}</code>——<code>available</code> 是「已登录且设置允许」，<code>paused</code> 在收到 401 后置上，直到下一次登录，<code>relay</code> 是中继自己的 <code>{enabled, cursor, counts{conversations, messages}, limits}</code>，问不到时为 <code>null</code>。<code>PUT {enabled: false}</code> 在这里关掉同步，并删掉中继为这个账号保存的内容（其他设备的开关会在它们下一次推送或拉取时跟着关，中继会以 <code>sync_off</code> 拒绝）；<code>PUT {enabled: true}</code> 重新打开，并把这里的聊天推上去。中继的拒绝会以它的状态码和代码原样返回（<code>409 sync_off</code>）。从 0.1.38 起，状态里还带 <code>side_chats</code>（这台设备的<em>同时同步旁聊</em>，默认关闭：只推送和拉取主要聊天）和 <code>working</code>（<code>[{thread, cid, device, device_name, at}]</code>——此刻正在回答的其他设备，来自 hub 的 <code>working</code> 帧，每条十分钟后丢弃）；<code>PUT {side_chats: true}</code> 把这台设备的旁聊发上去，并从头把账号的旁聊拉一次，<code>false</code> 则从此留在本地</td></tr><tr><td>POST</td><td><code>/api/sync/delete</code></td><td>删掉中继上每一段已同步的对话，开关保持原样；返回状态</td></tr><tr><td>POST</td><td><code>/api/sync/pull</code></td><td>现在就抓取并应用其他设备的改动：<code>{applied, …state}</code></td></tr><tr><td>GET</td><td><code>/api/browser/{thread}/frames/{id}.jpg</code></td><td>一帧浏览器画面（JPEG，当前会话期间留在内存里）</td></tr><tr><td>POST</td><td><code>/api/browser/{thread}/control</code> <code>{action: click(x,y as 0–1 fractions) · type(text) · key(key) · scroll(dy) · navigate(url) · look · handed_back}</code></td><td>你来开智能体的浏览器；<code>handed_back</code> 是 Android 应用在你关掉它的接管面板时发的（取一帧新画面，告知智能体）；浏览器没打开时返回 <code>409</code>（先打开一个 URL）</td></tr><tr><td>GET</td><td><code>/api/push</code></td><td><code>{available, public_key, subscriptions, devices[]}</code>——用来订阅的 VAPID 公钥</td></tr><tr><td>POST</td><td><code>/api/push/subscribe</code> <code>{subscription}</code>、<code>/api/push/unsubscribe</code> <code>{endpoint}</code></td><td>注册 / 删掉这台设备的 <code>PushSubscription</code></td></tr><tr><td>POST</td><td><code>/api/push/test</code></td><td>给每台已订阅的设备发一条测试通知</td></tr><tr><td>WS</td><td><code>/ws</code></td><td>实时事件；第一帧是 <code>{&quot;kind&quot;: &quot;auth&quot;, &quot;token&quot;: …}</code></td></tr></tbody></table><h3 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket {#websocket}&quot;">​</a></h3><p>客户端的第一帧是 <code>{&quot;kind&quot;: &quot;auth&quot;, &quot;token&quot;: &quot;…&quot;}</code>（十秒之内，否则 socket 以 4401 关闭——令牌错了也一样）。然后服务器发 <code>{&quot;kind&quot;: &quot;hello&quot;, &quot;state&quot;: …}</code>（和 <code>/api/state</code> 同样的内容）。接下来：</p><table tabindex="0"><thead><tr><th>服务器 → 客户端</th><th>含义</th></tr></thead><tbody><tr><td><code>event</code></td><td>一条新的时间线事件（<code>user</code>、<code>assistant</code>、<code>tool</code>、<code>approval</code>、<code>question</code>、<code>artifact</code>、<code>browser</code>、<code>notice</code>）。<code>approval</code> 带 <code>summary</code>、<code>purpose</code>（你当初要的是什么）、<code>target</code>、<code>grant_key</code>、<code>grant_options</code>、<code>risk</code>、<code>warnings</code>、<code>args</code>。<code>browser</code> 卡片带 <code>url</code>、<code>title</code>、<code>action</code>、<code>frame</code>（最新一张图的 id）、<code>frames</code>、<code>status</code>（<code>live</code> / <code>done</code>）、<code>by_user</code>、<code>backend</code>（<code>playwright</code> 或 <code>device</code>）以及这帧画面以 CSS 像素计的 <code>width</code> / <code>height</code>。后台轮次里产生的事件带 <code>source: &quot;background&quot;</code> 和 <code>about</code>（这一轮的标签）。结束一轮的那条 <code>assistant</code> 气泡带 <code>final: true</code>（发出时就设上，或者气泡已经在屏幕上时以一条 <code>update</code> 补上）；在它之前一步一步的叙述不带——把后台结果映射成通知的客户端应该以这个标志为准</td></tr><tr><td><code>update</code></td><td>已有事件的字段变了（一个工具跑完了、一张审批有了结果、一张浏览器卡片有了新的一帧）</td></tr><tr><td><code>event_removed</code></td><td><code>{thread, id}</code>——一条事件离开了时间线：在账号的另一台设备上删掉了一条消息（对话同步）</td></tr><tr><td><code>working</code></td><td><code>{thread, cid, device, device_name, working, at}</code>——账号的另一台设备在一段同步的对话里开始（<code>true</code>）或结束（<code>false</code>）了一轮；为 <code>true</code> 期间应用在最后一条消息下面显示「{device} 正在处理…」，回复到了或者十分钟后撤掉。<code>hello</code> 的状态在 <code>working</code> 下列出正在进行的那些</td></tr><tr><td><code>stream_start</code> / <code>delta</code> / <code>stream_end</code></td><td>正在生成的助手回复；流出来的内容最后发现不是回复时（提示词模式的工具调用、安静的后台轮次），<code>stream_end</code> 带 <code>discard: true</code></td></tr><tr><td><code>status</code></td><td>idle / working / waiting，附一行简短说明</td></tr><tr><td><code>thread</code>、<code>thread_cleared</code>、<code>thread_deleted</code></td><td>会话列表的变化</td></tr><tr><td><code>firstrun</code></td><td><code>{firstrun}</code>——第一次对话往前走了一步（「开始」、模型的 <code>nanomuse-naming</code> 代码块、选了名字、撤掉卡片）：和 <code>GET /api/firstrun</code> 同样的视图，不带 <code>intro</code>；聊天据此重画起名卡片。<code>hello</code> 的状态在 <code>firstrun</code> 下带着它</td></tr><tr><td><code>goals</code>、<code>memory</code>、<code>ideas</code>、<code>feed_posts</code>、<code>profile</code>、<code>settings</code>、<code>connections</code>、<code>skills</code>、<code>approvals_reset</code></td><td>给各标签页的刷新提示</td></tr><tr><td><code>phone</code></td><td>一台手机连上或离开了：<code>/api/phone</code> 的视图</td></tr><tr><td><code>schedule</code></td><td><code>next_wake_at</code> 变了（设了或触发了一条提醒、某个目标的节奏变了、免打扰时段结束了）：<code>{next_wake_at}</code>，没有到期事项时为 <code>null</code>。Android 运行时据此重设它的闹钟</td></tr><tr><td><code>device_ack</code>、<code>device_request</code></td><td>发给连着的手机：对它的通告的回应，以及要它的屏幕或要它做一个动作的请求（<a href="./gui#the-device-protocol">gui.md</a>）</td></tr><tr><td><code>error</code>、<code>pong</code></td><td>对客户端消息的答复</td></tr></tbody></table><p>客户端 → 服务器：<code>{&quot;kind&quot;: &quot;send&quot;, &quot;thread&quot;: &quot;main&quot;, &quot;text&quot;: &quot;…&quot;, &quot;language&quot;: &quot;en&quot;}</code>（<code>language</code> 可选，含义同 <code>POST /api/threads/{id}/send</code>）、<code>{&quot;kind&quot;: &quot;approval&quot;, &quot;id&quot;: &quot;…&quot;, &quot;approved&quot;: true, &quot;scope&quot;: &quot;once&quot;}</code>、<code>{&quot;kind&quot;: &quot;ping&quot;}</code>。允许智能体操作自己的手机还会发一次 <code>{&quot;kind&quot;: &quot;device&quot;, …}</code>，并对每个请求回一条 <code>{&quot;kind&quot;: &quot;device_result&quot;, …}</code>。</p><p>时间线事件按会话持久化在 <code>&lt;data_dir&gt;/threads/&lt;id&gt;.json</code>，所以历史在重启后还在。</p><h2 id="developing-the-front-end" tabindex="-1">前端开发 <a class="header-anchor" href="#developing-the-front-end" aria-label="Permalink to &quot;前端开发 {#developing-the-front-end}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Vite on http://localhost:5173, proxied to the server on 8787</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # writes nanomuse/server/static/ — commit the result</span></span></code></pre></div><p>用开发服务器期间，在 <code>[server]</code> 里加上 <code>cors_origins = [&quot;http://localhost:5173&quot;]</code>。应用就是普通的 React + TypeScript + Tailwind，没有状态管理库；<code>web/src/store.tsx</code> 放着 reducer 和 WebSocket 客户端，<code>web/src/screens/</code> 每个标签页一个文件。</p>`,56)])])}const f=r(l,[["render",p]]);export{y as __pageData,f as default};
